#include "dispatch.hpp"

// Returns the number of side effects applied, or -1 on a rejected event.
int dispatch_event(Queue& q, const Event& e)
{
  if (q.draining) return -1;
  int applied = 0;
  if (e.kind == EventKind::KEY) {
    if (e.a < 0) return -1;
    applied = e.a > 127 ? 2 : 1;
  } else if (e.kind == EventKind::MOUSE) {
    if (e.a < 0 || e.b < 0) return -1;
    applied = 1;
    if (e.b > 0) applied += 1;
  } else if (e.kind == EventKind::RESIZE) {
    if (e.a <= 0 || e.b <= 0) return -1;
    q.pending.push_back(e);
    applied = 1;
  } else if (e.kind == EventKind::PAINT) {
    applied = q.pending.empty() ? 0 : 1;
    q.pending.clear();
  } else if (e.kind == EventKind::FOCUS) {
    applied = e.a ? 1 : 0;
  }
  return applied;
}

