  Queue q;
  assert(dispatch_event(q, {EventKind::RESIZE, 80, 24, false}) == 1);
  assert(dispatch_event(q, {EventKind::RESIZE, 90, 30, false}) == 1);
  assert(dispatch_event(q, {EventKind::SHUTDOWN, 0, 0, false}) == 2);
  assert(q.pending.empty());
